package com.metasongi.mapper;
import android.app.*;
import android.os.*;
import android.content.*;
import android.hardware.display.DisplayManager;
import android.view.*;
import android.widget.*;
import android.graphics.*;
import org.json.*;
import java.io.*;

public class MainActivity extends Activity implements DisplayManager.DisplayListener {
 private final float[] corners={.15f,.15f,.85f,.15f,.85f,.85f,.15f,.85f};
 private Bitmap image;private MappingView editor,output;private Presentation presentation;private DisplayManager dm;private TextView status;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setBackgroundColor(Color.BLACK);status=new TextView(this);status.setTextColor(Color.WHITE);status.setText("Drag the four corner handles. Images only MVP.");layout.addView(status);LinearLayout row=new LinearLayout(this);layout.addView(row);button(row,"Image",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);});button(row,"Save",()->save());button(row,"Load",()->load());button(row,"Reset",()->{float[] v={.15f,.15f,.85f,.15f,.85f,.85f,.15f,.85f};System.arraycopy(v,0,corners,0,8);redraw();});editor=new MappingView(this,true);layout.addView(editor,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);dm=(DisplayManager)getSystemService(DISPLAY_SERVICE);dm.registerDisplayListener(this,new Handler(Looper.getMainLooper()));connect();}
 private void button(LinearLayout row,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setOnClickListener(v->action.run());row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}
 private void connect(){if(presentation!=null){presentation.dismiss();presentation=null;output=null;}Display[] displays=dm.getDisplays(DisplayManager.DISPLAY_CATEGORY_PRESENTATION);if(displays.length==0){status.setText("Preview only. Connect a supported HDMI display.");return;}try{presentation=new Presentation(this,displays[0]);output=new MappingView(presentation.getContext(),false);presentation.setContentView(output);presentation.show();status.setText("Projector connected. Editing handles stay on phone.");}catch(WindowManager.InvalidDisplayException e){status.setText("Display unavailable: "+e.getMessage());}}
 @Override public void onDisplayAdded(int id){connect();}@Override public void onDisplayRemoved(int id){connect();}@Override public void onDisplayChanged(int id){connect();}
 @Override protected void onDestroy(){if(dm!=null)dm.unregisterDisplayListener(this);if(presentation!=null)presentation.dismiss();super.onDestroy();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==1&&result==RESULT_OK&&data!=null){try(InputStream stream=getContentResolver().openInputStream(data.getData())){byte[] bytes=readBytes(stream);BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);opts.inSampleSize=1;while(opts.outWidth/opts.inSampleSize>2048||opts.outHeight/opts.inSampleSize>2048)opts.inSampleSize*=2;opts.inJustDecodeBounds=false;Bitmap decoded=BitmapFactory.decodeByteArray(bytes,0,bytes.length,opts);if(decoded==null)throw new IOException("Invalid image");image=decoded;try(FileOutputStream out=openFileOutput("image.png",MODE_PRIVATE)){image.compress(Bitmap.CompressFormat.PNG,100,out);}redraw();}catch(Exception e){status.setText("Image error: "+e.getMessage());}}}
 private byte[] readBytes(InputStream input)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=input.read(buf))!=-1){if(out.size()+n>20*1024*1024)throw new IOException("Image must be under 20MB");out.write(buf,0,n);}return out.toByteArray();}
 private void redraw(){editor.invalidate();if(output!=null)output.invalidate();}
 private boolean convex(float[] p){float sign=0;for(int i=0;i<4;i++){int a=i*2,b=((i+1)%4)*2,c=((i+2)%4)*2;float cross=(p[b]-p[a])*(p[c+1]-p[b+1])-(p[b+1]-p[a+1])*(p[c]-p[b]);if(Math.abs(cross)<.002f)return false;if(sign!=0&&cross*sign<0)return false;sign=cross;}return true;}
 private void save(){try{JSONArray a=new JSONArray();for(float x:corners)a.put(x);try(FileOutputStream f=openFileOutput("mapping.json",MODE_PRIVATE)){f.write(a.toString().getBytes("UTF-8"));}status.setText("Saved mapping + last imported image");}catch(Exception e){status.setText(e.getMessage());}}
 private void load(){try{JSONArray a=new JSONArray(new String(readBytes(openFileInput("mapping.json")),"UTF-8"));if(a.length()!=8)throw new IOException("Expected 4 corners");float[] p=new float[8];for(int i=0;i<8;i++){p[i]=(float)a.getDouble(i);if(Float.isNaN(p[i])||Float.isInfinite(p[i])||p[i]<0||p[i]>1)throw new IOException("Invalid coordinate");}if(!convex(p))throw new IOException("Invalid quadrilateral");System.arraycopy(p,0,corners,0,8);File f=new File(getFilesDir(),"image.png");if(f.exists())image=BitmapFactory.decodeFile(f.getAbsolutePath());redraw();status.setText("Loaded");}catch(Exception e){status.setText("Load: "+e.getMessage());}}
 class MappingView extends View {
  final boolean editable;final Paint paint=new Paint(3);int selected=-1;
  MappingView(Context c,boolean edit){super(c);editable=edit;}
  protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.drawColor(Color.BLACK);float[] dst=new float[8];for(int i=0;i<4;i++){dst[2*i]=corners[2*i]*getWidth();dst[2*i+1]=corners[2*i+1]*getHeight();}Path path=new Path();path.moveTo(dst[0],dst[1]);for(int i=1;i<4;i++)path.lineTo(dst[i*2],dst[i*2+1]);path.close();canvas.save();canvas.clipPath(path);if(image!=null){Matrix m=new Matrix();float[] src={0,0,image.getWidth(),0,image.getWidth(),image.getHeight(),0,image.getHeight()};if(m.setPolyToPoly(src,0,dst,0,4))canvas.drawBitmap(image,m,paint);}else{paint.setColor(Color.rgb(25,180,175));canvas.drawPath(path,paint);paint.setColor(Color.WHITE);for(int x=0;x<getWidth();x+=60)canvas.drawLine(x,0,x,getHeight(),paint);for(int y=0;y<getHeight();y+=60)canvas.drawLine(0,y,getWidth(),y,paint);}canvas.restore();if(editable){paint.setColor(Color.YELLOW);for(int i=0;i<4;i++)canvas.drawCircle(dst[i*2],dst[i*2+1],18,paint);}}
  @Override public boolean onTouchEvent(android.view.MotionEvent e){if(!editable)return false;if(e.getAction()==MotionEvent.ACTION_DOWN){float best=80;selected=-1;for(int i=0;i<4;i++){float d=(float)Math.hypot(e.getX()-corners[2*i]*getWidth(),e.getY()-corners[2*i+1]*getHeight());if(d<best){best=d;selected=i;}}return true;}if(e.getAction()==MotionEvent.ACTION_MOVE&&selected>=0){float[] candidate=corners.clone();candidate[selected*2]=Math.max(0,Math.min(1,e.getX()/getWidth()));candidate[selected*2+1]=Math.max(0,Math.min(1,e.getY()/getHeight()));if(convex(candidate)){System.arraycopy(candidate,0,corners,0,8);redraw();}return true;}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){selected=-1;performClick();return true;}return true;}
  @Override public boolean performClick(){super.performClick();return true;}
 }
}
